311	
312	/**
313	 * A per-mailbox sieve filter as stored in Mailcow's `sieve_filters` table.
314	 *
315	 * Mailcow chains scripts as: global_sieve_before -> user `prefilter` ->
316	 * the user's own personal script -> user `postfilter` -> global_sieve_after.
317	 * Only ONE filter per (username, filter_type) can be active at a time —
318	 * Mailcow deactivates the others whenever a filter is added/edited as active.
319	 * That is why lib/mail/sieve.ts compiles auto-reply AND forwarding into a
320	 * single managed script instead of one filter each.
321	 */
322	export type MailcowFilter = {
323	  id: number;
324	  username: string;
325	  scriptDesc: string;
326	  scriptData: string;
327	  filterType: string; // "prefilter" | "postfilter"
328	  active: boolean;
329	};
330	
331	export type MailcowFilterType = "prefilter" | "postfilter";
332	
333	function toFilterRows(res: unknown): MailcowFilter[] {
334	  const rows = Array.isArray(res) ? res : [];
335	  const out: MailcowFilter[] = [];
336	  for (const r of rows) {
337	    if (!r || typeof r !== "object") continue;
338	    const o = r as Record<string, unknown>;
339	    const id = Number(o.id);
340	    if (!Number.isFinite(id)) continue;
341	    out.push({
342	      id,
343	      username: typeof o.username === "string" ? o.username : "",
344	      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
345	      scriptData: typeof o.script_data === "string" ? o.script_data : "",
346	      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
347	      active: toActive(o.active),
348	    });
349	  }
350	  return out;
351	}
