353	/**
354	 * List the sieve filters belonging to ONE mailbox
355	 * (`GET /get/filters/<address>`). Mailcow returns `{}` when there are none.
356	 *
357	 * Always pass a full address: `/get/filters/all` walks every domain on the
358	 * server, which would leak other tenants' scripts into our result.
359	 */
360	export async function mcListFilters(address: string): Promise<MailcowFilter[]> {
361	  const res = await mcRequest("GET", `/get/filters/${encodeURIComponent(address)}`);
362	  // Defence in depth: Mailcow scopes by username server-side, but we re-filter
363	  // so a wrong/greedy response can never hand one customer another's script.
364	  const want = address.trim().toLowerCase();
365	  return toFilterRows(res).filter((f) => f.username.trim().toLowerCase() === want);
366	}
