415	// ---------- DKIM ----------
416	
417	/**
418	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
419	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
420	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
421	 * or null when the domain has no DKIM key yet or the shape is unexpected.
422	 *
423	 * Throws MailcowError only when the integration is unreachable/errors — callers
424	 * that must stay tolerant wrap this in try/catch.
425	 */
426	export async function mcGetDkim(domain: string): Promise<string | null> {
427	  return (await mcGetDkimDetails(domain))?.txt ?? null;
428	}
429	
430	/** The signing key Mailcow will actually use, plus the selector it publishes under. */
431	export type MailcowDkim = { selector: string; txt: string; bits: number | null };
432	
433	/**
434	 * Fetch the LIVE DKIM key + selector for a domain.
435	 *
436	 * The deliverability self-check must compare published DNS against this, never
437	 * against `EmailSubscription.dkimRecord`: that column is a cache written once at
438	 * DNS-setup time, so if the key is ever rotated (or the domain re-created on
439	 * Mailcow, which regenerates it) the cache silently describes a key that no
440	 * longer signs anything — and the check would tell a customer their DNS is
441	 * correct while every message they send fails DKIM.
442	 */
443	export async function mcGetDkimDetails(domain: string): Promise<MailcowDkim | null> {
444	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
445	  if (!res || typeof res !== "object") return null;
446	  // Mailcow returns {} for a domain with no key configured.
447	  const o = res as Record<string, unknown>;
448	  const txt = typeof o.dkim_txt === "string" ? o.dkim_txt.trim() : "";
449	  if (!txt) return null;
450	  const selector = typeof o.dkim_selector === "string" && o.dkim_selector.trim() ? o.dkim_selector.trim() : "dkim";
451	  const bits = Number(o.length);
452	  return { selector, txt, bits: Number.isFinite(bits) && bits > 0 ? bits : null };
453	}
