457	export type MailStats = {
458	  configured: true;
459	  domains: number;
460	  mailboxes: number;
461	  postfix: {
462	    sampled: number;
463	    sent: number;
464	    deferred: number;
465	    bounced: number;
466	    rejected: number;
467	    other: number;
468	  };
469	  rspamd: {
470	    sampled: number;
471	    actions: Record<string, number>;
472	    spam: number; // reject + add header + rewrite subject
473	    clean: number; // no action + greylist / soft reject
474	  };
475	};
476	
477	function asArray(v: unknown): unknown[] {
478	  if (Array.isArray(v)) return v;
479	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
480	    return (v as { rows: unknown[] }).rows;
481	  }
482	  return [];
