111	 * `verified: true` is load-bearing, not decoration. An alias is a mail-routing
112	 * change (`mcAddAlias` makes the shared Mailcow deliver an address somewhere),
113	 * so treating a bare subscription row as proof of domain control let a claimed —
114	 * not owned — domain silently intercept inbound mail. Same root cause as the
115	 * 2026-07-25 cross-tenant takeover: owning the ROW is not owning the DOMAIN.
116	 */
117	async function ownedDomains(userId: string): Promise<Set<string>> {
118	  const subs = await db.emailSubscription.findMany({
119	    where: { userId, status: { not: "CANCELLED" }, verified: true },
120	    select: { domainName: true },
121	  });
122	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
