232	// ---------------------------------------------------------------------------
233	// Server-side rules: auto-reply + forwarding, as real Mailcow sieve filters
234	// ---------------------------------------------------------------------------
235	//
236	// These two were STORE-ONLY: the panel wrote the DB, showed a green "Saved",
237	// and NOTHING on the mail server changed. A customer switching on an
238	// out-of-office before a holiday got no auto-replies and no forwarded mail. The
239	// old comments claimed the API had no primitive for this; it does —
240	// `POST /add|edit|delete/filter` drives Dovecot sieve per mailbox (see
241	// lib/mail/sieve.ts for the capability audit).
242	//
243	// The whole rule set is compiled into ONE managed script and pushed BEFORE the
244	// DB is written, so the stored preference and the live server never disagree.
245	// If Mailcow rejects the push the DB is left untouched and the customer sees the
246	// failure — the opposite of the "Saved" lie this replaces.
247	
248	/** Live state of the managed sieve script, read back from the mail server. */
249	export type MailRuleStatus = {
250	  /** Rules can be enforced at all (Mailcow configured + reachable + domain verified). */
251	  supported: boolean;
252	  /** The server is currently running our auto-reply / forwarding rule. */
253	  autoReplyLive: boolean;
254	  forwardingLive: boolean;
255	  /** Why enforcement is unavailable, when it is. */
256	  error?: string;
257	};
