259	/** Load the rule columns for a mailbox we have already ownership-checked. */
260	async function ruleState(mailboxId: string, address: string): Promise<MailboxRuleState> {
261	  const row = await db.mailbox.findUnique({
262	    where: { id: mailboxId },
263	    select: {
264	      autoReplyEnabled: true,
265	      autoReplySubject: true,
266	      autoReplyBody: true,
267	      autoReplyStart: true,
268	      autoReplyEnd: true,
269	      forwardingAddress: true,
270	      forwardKeepCopy: true,
271	    },
272	  });
273	  return {
274	    address,
275	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
276	    autoReplySubject: row?.autoReplySubject ?? null,
277	    autoReplyBody: row?.autoReplyBody ?? null,
278	    autoReplyStart: row?.autoReplyStart ?? null,
279	    autoReplyEnd: row?.autoReplyEnd ?? null,
280	    forwardingAddress: row?.forwardingAddress ?? null,
281	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
282	  };
