356	/**
357	 * Report what the mail server is ACTUALLY running, so the panel can stop
358	 * guessing. Derived from the live script's markers, not from the DB — if a rule
359	 * was never applied (or was removed on the server) this says so.
360	 */
361	export async function getMailRuleStatus(mailboxAddress?: string): Promise<MailRuleStatus> {
362	  const { address, subscription } = await resolveMailbox(mailboxAddress);
363	  const blocked = assertRulesAllowed(subscription);
364	  if (blocked) return { supported: false, autoReplyLive: false, forwardingLive: false, error: blocked.error };
365	
366	  try {
367	    const mine = (await mcListFilters(address)).find((f) => isNxeonSieve(f.scriptDesc) && f.active);
368	    return {
369	      supported: true,
370	      autoReplyLive: Boolean(mine?.scriptData.includes(MARK_AUTOREPLY)),
371	      forwardingLive: Boolean(mine?.scriptData.includes(MARK_FORWARD)),
372	    };
373	  } catch (e) {
374	    return {
375	      supported: false,
376	      autoReplyLive: false,
377	      forwardingLive: false,
378	      error: `Couldn't reach the mail server to read your rules: ${friendly(e)}`,
379	    };
380	  }
381	}
