383	/**
384	 * Forward inbound mail to another address, enforced by a real sieve `redirect`.
385	 * "Keep a copy" maps to `redirect :copy` (implicit keep survives); without it a
386	 * bare `redirect` + `stop` forwards without local delivery.
387	 */
388	export async function saveForwarding(
389	  input: { enabled: boolean; address?: string; keepCopy?: boolean },
390	  mailboxAddress?: string,
391	): Promise<Result> {
392	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
393	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
394	  if (limited) return limited;
395	
396	  const enabled = Boolean(input.enabled);
397	  const target = (input.address ?? "").trim().toLowerCase();
398	  const keepCopy = input.keepCopy !== false;
399	
400	  if (enabled) {
401	    if (!target) return { ok: false, error: "Enter an address to forward to." };
402	    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
403	    if (target.length > 200) return { ok: false, error: "That address is too long." };
404	    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
405	  }
406	
407	  const blocked = assertRulesAllowed(subscription);
408	  if (blocked) return blocked;
409	
410	  const next: MailboxRuleState = {
411	    ...(await ruleState(mailboxId, address)),
412	    forwardingAddress: enabled && target ? target : null,
413	    forwardKeepCopy: keepCopy,
414	  };
415	
416	  try {
417	    await pushMailboxSieve(next);
418	  } catch (e) {
419	    // Deliberately do NOT persist: a stored "forwarding on" that the server is
420	    // not running is the exact defect this replaces.
421	    return { ok: false, error: `Couldn't apply forwarding on the mail server: ${friendly(e)}` };
422	  }
423	
424	  await db.mailbox.update({
425	    where: { id: mailboxId },
426	    data: { forwardingAddress: next.forwardingAddress, forwardKeepCopy: next.forwardKeepCopy },
427	  });
428	
429	  await db.auditLog
430	    .create({
431	      data: {
432	        userId: user.id,
433	        action: "mailbox.forwarding",
434	        detail: `${address} → ${next.forwardingAddress ?? "off"}${next.forwardingAddress && !keepCopy ? " (no local copy)" : ""}`,
435	      },
436	    })
437	    .catch(() => {});
438	
439	  return { ok: true };
440	}
