442	/**
443	 * Out-of-office responder, enforced by a real sieve `vacation`. The date window
444	 * is compiled into the script as a `currentdate` test so the mail server starts
445	 * and stops replying on its own — nothing here runs on a schedule, so a window
446	 * evaluated in this process would simply never stop.
447	 */
448	export async function saveAutoReply(
449	  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
450	  mailboxAddress?: string,
451	): Promise<Result> {
452	  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
453	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
454	  if (limited) return limited;
455	
456	  const enabled = Boolean(input.enabled);
457	  const subject = (input.subject ?? "").trim();
458	  const body = (input.body ?? "").trim();
459	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
460	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
461	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
462	
463	  const start = fromDateInput(input.start);
464	  const end = fromDateInput(input.end);
465	  if (start && end && start.getTime() > end.getTime()) {
466	    return { ok: false, error: "The start date must be on or before the end date." };
467	  }
468	
469	  const blocked = assertRulesAllowed(subscription);
470	  if (blocked) return blocked;
471	
472	  const next: MailboxRuleState = {
473	    ...(await ruleState(mailboxId, address)),
474	    autoReplyEnabled: enabled,
475	    autoReplySubject: subject || null,
476	    autoReplyBody: body || null,
477	    autoReplyStart: start,
478	    autoReplyEnd: end,
479	  };
480	
481	  try {
482	    await pushMailboxSieve(next);
483	  } catch (e) {
484	    return { ok: false, error: `Couldn't apply the auto-reply on the mail server: ${friendly(e)}` };
485	  }
486	
487	  await db.mailbox.update({
488	    where: { id: mailboxId },
489	    data: {
490	      autoReplyEnabled: next.autoReplyEnabled,
491	      autoReplySubject: next.autoReplySubject,
492	      autoReplyBody: next.autoReplyBody,
493	      autoReplyStart: next.autoReplyStart,
494	      autoReplyEnd: next.autoReplyEnd,
495	    },
496	  });
497	
498	  await db.auditLog
499	    .create({
500	      data: {
501	        userId: user.id,
502	        action: "mailbox.autoreply",
503	        detail: `${address} → ${enabled ? "on" : "off"}`,
504	      },
505	    })
506	    .catch(() => {});
507	
508	  return { ok: true };
509	}
