317	// Attachment limits — enforced server-side; never trust the client's own caps.
318	const MAX_ATTACHMENTS = 10;
319	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB decoded
320	
321	// Base64 inflates by ~4/3, so 20 MB of files arrives as ~26.7 MB of payload.
322	// `next.config.ts` raises `experimental.serverActions.bodySizeLimit` to 30 MB to
323	// match (Next's 1 MB default silently truncated anything over ~700 KB while both
324	// this file and the composer advertised 20 MB). This ceiling is the server-side
325	// half of that pairing: it rejects an over-large upload with a message the
326	// customer can act on, instead of letting Buffer.from allocate first.
327	const MAX_ATTACHMENTS_TOTAL_BASE64 = Math.ceil(MAX_ATTACHMENTS_TOTAL_BYTES / 3) * 4;
328	
329	/** Human-friendly byte size for limit messages (mirrors the composer's format). */
330	function fmtLimit(bytes: number): string {
331	  return `${Math.round(bytes / (1024 * 1024))} MB`;
332	}
333	
334	/** Strip path separators, quotes and control chars from an attachment filename. */
335	function sanitizeAttachmentName(name?: string): string {
336	  if (!name) return "";
337	  const cleaned = Array.from(name)
338	    .filter((ch) => {
339	      const c = ch.codePointAt(0) ?? 0;
340	      if (c < 0x20 || c === 0x7f) return false; // control chars
341	      if (ch === '"' || ch === "\\" || ch === "/") return false;
342	      return true;
343	    })
344	    .join("");
345	  return cleaned.trim().slice(0, 200);
346	}
347	
348	type BuiltAttachment = { filename: string; content: Buffer; contentType: string };
349	
350	/**
351	 * Validate + decode client-supplied attachments. Caps count and total decoded
352	 * size, validates base64, sanitises filenames and defaults the content type.
353	 * Returns the decoded buffers or a friendly error string.
354	 */
355	function decodeAttachments(
356	  input: SendAttachment[] | undefined,
357	): { ok: true; attachments: BuiltAttachment[] } | { ok: false; error: string } {
358	  if (!input || input.length === 0) return { ok: true, attachments: [] };
359	  if (!Array.isArray(input)) return { ok: false, error: "Invalid attachments." };
360	  if (input.length > MAX_ATTACHMENTS) {
361	    return { ok: false, error: `Too many attachments — up to ${MAX_ATTACHMENTS} allowed.` };
362	  }
363	
364	  // Reject on the ENCODED length before decoding anything, so an oversize upload
365	  // fails with a clear message rather than being decoded into memory first.
366	  let encodedTotal = 0;
367	  for (const a of input) {
368	    if (a && typeof a.contentBase64 === "string") encodedTotal += a.contentBase64.length;
369	  }
370	  if (encodedTotal > MAX_ATTACHMENTS_TOTAL_BASE64) {
371	    return {
372	      ok: false,
373	      error: `Attachments are too large — the total must be under ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)}. Remove a file or send it as a link.`,
374	    };
375	  }
376	
377	  const out: BuiltAttachment[] = [];
378	  let total = 0;
379	  for (let i = 0; i < input.length; i++) {
380	    const a = input[i];
381	    if (!a || typeof a.contentBase64 !== "string") {
382	      return { ok: false, error: "Invalid attachment data." };
383	    }
384	    // Tolerate a stray "data:*;base64," prefix, then validate the base64.
385	    const b64 = a.contentBase64.replace(/^data:[^;]*;base64,/, "").trim();
386	    if (!/^[A-Za-z0-9+/]*={0,2}$/.test(b64) || b64.length % 4 !== 0) {
387	      return { ok: false, error: "Attachment could not be read (invalid encoding)." };
388	    }
389	    const content = Buffer.from(b64, "base64");
390	    total += content.length;
391	    if (total > MAX_ATTACHMENTS_TOTAL_BYTES) {
392	      return {
393	        ok: false,
394	        error: `Attachments exceed the ${fmtLimit(MAX_ATTACHMENTS_TOTAL_BYTES)} total limit.`,
395	      };
396	    }
397	    const filename = sanitizeAttachmentName(a.filename) || `attachment-${i + 1}`;
398	    const contentType =
399	      typeof a.contentType === "string" && a.contentType.trim()
400	        ? a.contentType.trim().slice(0, 128)
401	        : "application/octet-stream";
402	    out.push({ filename, content, contentType });
403	  }
404	  return { ok: true, attachments: out };
405	}
