407	/**
408	 * Send a message from the user's own mailbox over SMTP submission, append a copy
409	 * to Sent, and (for replies) thread it + flag the original \Answered.
410	 */
411	export async function sendMessage(
412	  payload: SendPayload,
413	  mailboxAddress?: string,
414	): Promise<{ ok: boolean; error?: string }> {
415	  const { user, cred, identity } = await resolveMailbox(mailboxAddress);
416	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
417	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
418	
419	  const to = parseRecipients(payload.to);
420	  const cc = parseRecipients(payload.cc);
421	  const bcc = parseRecipients(payload.bcc);
422	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
423	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
424	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
425	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
426	    return { ok: false, error: "Nothing to send — add a subject or a message." };
427	  }
428	
429	  const decoded = decodeAttachments(payload.attachments);
430	  if (!decoded.ok) return { ok: false, error: decoded.error };
431	  const attachments = decoded.attachments;
432	
433	  try {
434	    // Look up threading headers when this is a reply.
435	    let inReplyTo: string | undefined;
436	    let references: string | undefined;
437	    if (payload.inReplyToUid && payload.replyFolder) {
438	      try {
439	        await withMailbox(cred, payload.replyFolder, async (client) => {
440	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
441	          if (orig && orig.envelope?.messageId) {
442	            inReplyTo = orig.envelope.messageId;
443	            references = orig.envelope.messageId;
444	          }
445	          // Mark the message we're replying to as answered (best effort).
446	          try {
447	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
448	          } catch {
449	            /* ignore */
450	          }
451	        });
452	      } catch {
453	        /* original not found — send without threading headers */
454	      }
455	    }
456	
457	    // Apply the saved sender identity.
458	    //
459	    // These three columns were written by the Identity panel and read by NOTHING:
460	    // the panel promised "Shown as the sender name on messages you send" and every
461	    // message still went out bare `from: cred.address` with no Reply-To, so a
462	    // customer who set a reply-to address had replies quietly go to the wrong
463	    // mailbox. Each field falls back to the previous behaviour when unset.
464	    //
465	    // Note `from` only changes the HEADER. nodemailer derives `built.envelope`
466	    // from the address part, so SMTP MAIL FROM stays the authenticated mailbox
467	    // and SPF/DKIM alignment (fixed today) is untouched.
468	    const displayName = identity.displayName?.trim();
469	    const replyTo = identity.replyTo?.trim();
470	    const organization = identity.organization?.trim();
471	
472	    // Compile the message once so the exact bytes are both sent and saved to Sent.
473	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
474	    const built = await composer.sendMail({
475	      from: displayName ? { name: displayName, address: cred.address } : cred.address,
476	      replyTo: replyTo || undefined,
477	      to: to.list,
478	      cc: cc.list.length ? cc.list : undefined,
479	      bcc: bcc.list.length ? bcc.list : undefined,
480	      subject: payload.subject || "",
481	      text: payload.text || undefined,
482	      html: payload.html || undefined,
483	      attachments: attachments.length ? attachments : undefined,
484	      inReplyTo,
485	      references,
486	      headers: organization ? { Organization: organization } : undefined,
487	    });
488	    const raw = built.message as Buffer;
489	
490	    const smtp = nodemailer.createTransport({
491	      host: MAIL_SMTP_HOST,
492	      port: MAIL_SMTP_PORT,
493	      secure: MAIL_SMTP_PORT === 465,
494	      requireTLS: MAIL_SMTP_PORT !== 465,
495	      tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
496	      auth: { user: cred.address, pass: cred.password },
497	    });
498	    await smtp.sendMail({ envelope: built.envelope, raw });
499	
500	    // Save a copy to Sent (best effort — the message already went out).
501	    try {
502	      await withImap(cred, async (client) => {
503	        const sentPath = await findSentPath(client);
504	        await client.append(sentPath, raw, ["\\Seen"]);
505	      });
506	    } catch {
507	      /* Sent append failed — not fatal */
508	    }
509	
510	    return { ok: true };
511	  } catch (e) {
512	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
513	  }
514	}
