188	/**
189	 * Why the caller can't open webmail, so the UI can say what is actually wrong
190	 * instead of one catch-all "No mailbox connected".
191	 */
192	export type MailAccessState =
193	  | { kind: "ok"; address: string }
194	  | { kind: "no-subscription" }
195	  | { kind: "unverified-domain"; domains: string[] }
196	  | { kind: "no-mailbox"; domains: string[] }
197	  | { kind: "no-password"; address: string }
198	  | { kind: "server-unreachable"; address: string };
