200	/**
201	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
202	 * that only exists on the server is found before we declare there is none.
203	 */
204	export async function mailAccessState(userId: string): Promise<MailAccessState> {
205	  await discoverMailboxes(userId).catch(() => 0);
206	
207	  const subs = await db.emailSubscription.findMany({
208	    where: { userId, status: { not: "CANCELLED" } },
209	    select: { domainName: true, verified: true, external: true },
210	  });
211	  if (subs.length === 0) return { kind: "no-subscription" };
212	
213	  const boxes = await db.mailbox.findMany({
214	    where: { subscription: { userId } },
215	    orderBy: { createdAt: "asc" },
216	    select: { address: true, passwordEnc: true },
217	  });
218	
219	  if (boxes.length === 0) {
220	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
221	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
222	    // An unverified domain is the more actionable problem: no mailbox can even
223	    // be created on it yet, so lead with that.
224	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
225	    return { kind: "no-mailbox", domains: verified };
226	  }
227	
228	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
229	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
230	
231	  // A mailbox and a credential exist, so the page's failure was the mail server
232	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
233	  return { kind: "server-unreachable", address: withPassword.address };
234	}
