300	/** Build a per-request imapflow client for the given credential. */
301	export function createImapClient(cred: MailboxCredentials): ImapFlow {
302	  return new ImapFlow({
303	    host: MAIL_IMAP_HOST,
304	    port: MAIL_IMAP_PORT,
305	    secure: true,
306	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
307	    // and validation servername so TLS verifies against the right name.
308	    servername: MAIL_TLS_SERVERNAME,
309	    tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
310	    auth: { user: cred.address, pass: cred.password },
311	    logger: false,
312	    disableAutoIdle: true,
313	  });
314	}
