316	/**
317	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
318	 * logout, falling back to a hard close). Suitable for one operation per request.
319	 */
320	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
321	  const client = createImapClient(cred);
322	  await client.connect();
323	  try {
324	    return await fn(client);
325	  } finally {
326	    try {
327	      await client.logout();
328	    } catch {
329	      try {
330	        client.close();
331	      } catch {
332	        /* already gone */
333	      }
334	    }
335	  }
336	}
