196	/**
197	 * Cloudflare "connect + auto-create" block. When the customer's domain is on
198	 * Cloudflare, one "Connect Cloudflare" click takes them to Cloudflare's consent
199	 * screen and brings them back with every mail record already published — the
200	 * intent (this subscription) travels with the OAuth request. Already-connected
201	 * customers just get the "Auto-create DNS records" button. Credentials never
202	 * round-trip to the client.
203	 */
204	function CloudflarePanel({
205	  subscriptionId,
206	  domainName,
207	  connected,
208	  onConnected,
209	}: {
210	  subscriptionId: string;
211	  domainName: string;
212	  connected: boolean;
213	  onConnected: () => void;
214	}) {
215	  const [error, setError] = useState<string | null>(null);
216	  const [status, setStatus] = useState<string | null>(null);
217	  const [creating, startCreate] = useTransition();
218	
219	  function autoCreate() {
220	    setError(null);
221	    setStatus(null);
222	    startCreate(async () => {
223	      const res = await autoCreateEmailDns(subscriptionId);
224	      if (res?.error) setError(res.error);
225	      else if (res?.ok) {
226	        const n = res.created?.length ?? 0;
227	        setStatus(
228	          `Created/updated ${n} record${n === 1 ? "" : "s"} in Cloudflare${
229	            res.created && res.created.length ? `: ${res.created.join(", ")}` : ""
230	          }. Now hit Verify DNS below (allow a minute for propagation).`,
231	        );
232	      }
233	    });
234	  }
235	
236	  return (
237	    <div className="mt-3 rounded-lg border border-sky-500/30 bg-sky-500/[0.06] p-3">
238	      <div className="flex flex-wrap items-center gap-2">
239	        <Badge tone="slate">Cloudflare</Badge>
240	        <span className="text-sm font-semibold text-white">
241	          On Cloudflare? Let us add these records for you
242	        </span>
243	      </div>
244	
245	      {error && (
246	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
247	          {error}
248	        </div>
249	      )}
250	      {status && (
251	        <div className="mt-2 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-300">
252	          {status}
253	        </div>
254	      )}
255	
256	      <div className="mt-2">
257	        <p className="mb-2 text-xs text-slate-300">
258	          We&apos;ll create the MX, SPF, DKIM, DMARC and ownership records for{" "}
259	          <span className="font-mono">{domainName}</span> in your Cloudflare zone — no copying by
260	          hand. Existing records of the same kind are updated rather than duplicated.
261	        </p>
262	        <CloudflareConnect
