264	          id={subscriptionId}
265	          next="/dashboard/email"
266	          connectedHint={connected}
267	          onConnected={onConnected}
268	          what="add these records straight away"
269	        >
270	          <button className="btn-primary py-1.5 text-sm" onClick={autoCreate} disabled={creating}>
271	            {creating ? "Creating records…" : "Auto-create DNS records"}
272	          </button>
273	        </CloudflareConnect>
274	      </div>
275	    </div>
276	  );
277	}
