59	/**
60	 * Business Email — mailbox hosting per registered domain.
61	 *
62	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
63	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
64	 * which debits the wallet, then manages individual `Mailbox` rows under it.
65	 *
66	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
67	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
68	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
69	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
70	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
71	 * order flow; the row persists and can be retried via retryMailboxProvision.
72	 *
73	 * This module owns:
74	 *   - orderEmailHosting (customer subscribe)
75	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
76	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
77	 */
78	
79	type Result = { error?: string; ok?: boolean };
80	
81	/**
82	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
83	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
84	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
85	 * can be picked up once the integration is wired.
86	 */
87	async function provisionMailboxOnMailcow(mailbox: {
88	  id: string;
89	  address: string;
90	  quotaMB: number | null;
91	  subscription: { domainName: string };
92	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
93	  if (!mailcowConfigured()) return "PROVISIONING";
94	
95	  const [localPart] = mailbox.address.split("@");
96	  const domain = mailbox.subscription.domainName;
97	  const quotaMB = mailbox.quotaMB ?? 1024;
98	
99	  try {
100	    // Ensure the mail domain exists before adding the mailbox.
101	    if (!(await mcDomainExists(domain))) {
102	      // A concurrent create or pre-existing domain can still error here; ignore
103	      // and let the mailbox add be the real signal.
104	      await mcCreateDomain(domain).catch(() => {});
105	    }
106	
107	    const password = randomBytes(18).toString("base64url");
108	    await mcCreateMailbox({
109	      localPart,
110	      domain,
111	      name: mailbox.address,
112	      password,
113	      quotaMB,
114	    });
115	
116	    await db.mailbox.update({
117	      where: { id: mailbox.id },
118	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
119	    });
120	    return "ACTIVE";
121	  } catch (e) {
122	    await db.mailbox
123	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
124	      .catch(() => {});
125	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
126	    return "FAILED";
127	  }
128	}
