228	/**
229	 * Subscribe one of the caller's registered domains to an email plan. Validates
230	 * domain ownership + plan availability, then atomically debits the wallet and
231	 * creates the EmailSubscription with an expiry set from the plan term.
232	 *
233	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
234	 * provisioned with a mail provider yet — that integration is pending, and the
235	 * UI surfaces every mailbox as "provisioning" until it lands.
236	 */
237	export async function orderEmailHosting(
238	  domainName: string,
239	  emailPlanId: string,
240	): Promise<Result> {
241	  const user = await requireUser();
242	
243	  const name = String(domainName ?? "")
244	    .trim()
245	    .toLowerCase()
246	    .replace(/\.$/, "");
247	  if (!name) return { error: "Enter a domain." };
248	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
249	
250	  // Is the domain registered inside Nxeon? If so we control its DNS and can
251	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
252	  // verified via DNS before mail flows.
253	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
254	  const external = !inAccount;
255	
256	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
257	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
258	
259	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
260	  //
261	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
262	  // which let anyone buy a subscription for a domain another customer already
263	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
264	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
265	  // ADDRESS — so an attacker could create admin@victim.com under their own
266	  // subscription, call resetMailboxPassword() (which passes its ownership check
267	  // because the row is theirs), and have the password of the victim's real, live
268	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
269	  const dupe = await db.emailSubscription.findFirst({
270	    where: { domainName: name, status: { not: "CANCELLED" } },
271	  });
272	  if (dupe) {
273	    return {
274	      error:
275	        dupe.userId === user.id
276	          ? "This domain already has an email subscription."
277	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
278	    };
279	  }
280	
281	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
282	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
283	  // strikethrough shown on the pricing page is the real renewal price and this
284	  // discounted value is the real first-term price — displayed === charged.
285	  const promo = currentPromo(new Date());
286	  const chargeCents = promoPriceCents(plan.priceCents, promo);
287	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
288	  if (user.balanceCents < chargeCents) {
289	    return { error: "Insufficient balance. Top up your wallet first." };
290	  }
291	
292	  try {
293	    await db.$transaction(async (tx) => {
294	      await debitWallet(tx, user.id, chargeCents);
295	      await tx.walletTransaction.create({
296	        data: {
297	          userId: user.id,
298	          amountCents: -chargeCents,
299	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
300	        },
301	      });
302	      await tx.emailSubscription.create({
303	        data: {
304	          userId: user.id,
305	          domainName: name,
306	          emailPlanId: plan.id,
307	          status: "ACTIVE",
308	          autoRenew: true,
309	          expiresAt: addMonths(new Date(), plan.termMonths),
310	          // In-account domains: we control DNS, so treat as verified now. External
311	          // domains: not verified until the customer publishes DNS + we confirm it.
312	          external,
313	          verified: !external,
314	          verifiedAt: external ? null : new Date(),
315	          verifyToken: external ? randomBytes(24).toString("hex") : null,
316	        },
317	      });
318	    });
319	  } catch (e) {
320	    if (e instanceof InsufficientBalanceError) {
321	      return { error: "Insufficient balance. Top up your wallet first." };
322	    }
323	    throw e;
324	  }
325	
326	  await db.auditLog.create({
327	    data: {
328	      userId: user.id,
329	      action: "emailhosting.order",
330	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
331	    },
332	  });
333	  revalidatePath("/dashboard/email");
334	  return { ok: true };
335	}
