863	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
864	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
865	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
866	 * gracefully with clear messages for invalid token / zone-not-found.
867	 */
868	export async function autoCreateEmailDns(
869	  subscriptionId: string,
870	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
871	  const user = await requireUser();
872	
873	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
874	  if (!sub) return { error: "Subscription not found." };
875	  if (sub.userId !== user.id) return { error: "Not your subscription." };
876	  if (!sub.external) {
877	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
878	  }
879	
880	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
881	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
882	
883	  // Works for both connection shapes: OAuth credentials (refreshed here when
884	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
885	  const resolved = await resolveCloudflareToken(user);
886	  const token = resolved.token;
887	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
888	
889	  // Same record set the customer would otherwise publish by hand.
890	  const dns = await getEmailDnsRecords(subscriptionId);
891	  if (dns.error) return { error: dns.error };
892	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
893	  if (records.length === 0) {
894	    return { error: "No DNS records to create yet — try again in a moment." };
895	  }
896	
897	  // SANDBOX: never contact Cloudflare — report what we would have published so
898	  // staging can walk the whole "connect → records added" flow.
899	  if (SANDBOX) {
900	    return {
901	      ok: true,
902	      created: records.map((r) => `${r.label} (${r.type}, created)`),
903	    };
904	  }
905	
906	  let zoneId: string | null;
907	  try {
908	    zoneId = await cfFindZoneId(token, sub.domainName);
909	  } catch (e) {
910	    if (e instanceof CloudflareError) {
911	      return { error: `Cloudflare error: ${e.message}` };
912	    }
913	    throw e;
914	  }
915	  if (!zoneId) {
916	    return {
917	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
918	    };
919	  }
920	
921	  let created: string[];
922	  try {
923	    const results = await cfUpsertRecords(
924	      token,
925	      zoneId,
926	      records.map((r) => ({
927	        type: r.type,
928	        name: r.host,
929	        content: r.value,
930	        priority: r.priority,
931	      })),
932	    );
933	    created = results.map((res) => {
934	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
935	      return `${label} (${res.type}, ${res.action})`;
936	    });
937	  } catch (e) {
938	    if (e instanceof CloudflareError) {
939	      return {
940	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
941	      };
942	    }
943	    throw e;
944	  }
945	
946	  await db.auditLog.create({
947	    data: {
948	      userId: user.id,
949	      action: "cloudflare.autodns",
950	      detail: `${sub.domainName} — ${created.length} record(s)`,
951	    },
952	  });
953	  revalidatePath("/dashboard/email");
954	  return { ok: true, created };
955	}
