  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
  inReplyToUid?: number;
  replyFolder?: string;
};

// Attachment limits — mirrored server-side (the server re-validates and is the
// source of truth). Kept here only for fast, friendly client-side feedback.
const MAX_ATTACHMENTS = 10;
const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB

// A file the user has attached, already read into base64 in the browser.
type Attachment = {
  id: string;
  filename: string;
  contentType: string;
  size: number; // decoded byte size
  contentBase64: string;
};

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
  const mb = kb / 1024;
  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
}

// Read a File into raw base64 (stripping the "data:*;base64," prefix).
function readFileBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
    reader.onload = () => {
      const result = String(reader.result || "");
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.readAsDataURL(file);
  });
}

