const URL_ = pick("MAILCOW_API_URL");
const KEY = pick("MAILCOW_API_KEY");

async function liveDkim(domain: string) {
  const res = await fetch(`${URL_}/get/dkim/${domain}`, { headers: { "X-API-Key": KEY } });
  const j: any = await res.json();
  return j?.dkim_txt ? { selector: j.dkim_selector || "dkim", txt: j.dkim_txt } : null;
}

for (const domain of ["revsports.ca", "nxeon.cloud", "studionexis.com", "example-does-not-exist-zzz.com"]) {
  const dkim = await liveDkim(domain).catch(() => null);
  const r = await checkDeliverability({
    domain,
    mailHost: "mail.nxeon.cloud",
    spfInclude: "nxeon.cloud",
    spfExpected: "v=spf1 include:nxeon.cloud ~all",
    dmarcExpected: "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud",
    dkim,
  });
  console.log(`\n===== ${domain} =====`);
  console.log("nameservers queried:", r.nameservers.join(", ") || "(none)");
  if (r.error) console.log("error:", r.error);
  for (const c of r.checks) {
    console.log(`  [${c.status.toUpperCase().padEnd(7)}] ${c.key.padEnd(5)} ${c.host} (${c.type})`);
    console.log(`             observed: ${c.observed.slice(0, 100) || "(nothing published)"}`);
    console.log(`             detail  : ${c.detail}`);
  }
}

