import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { EmptyState } from "@/components/ui/primitives";
import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
import {
  listFolders,
  listMessages,
  getMailboxes,
} from "@/lib/actions-mail";
import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
import { mailAccessState, type MailAccessState } from "@/lib/mail/imap";
import { MailClient } from "@/components/customer/mail/MailClient";

export const dynamic = "force-dynamic";

export const metadata = { title: "Mail — Nxeon" };

export default async function MailPage({
  searchParams,
}: {
  searchParams: Promise<{ mailbox?: string }>;
}) {
  const user = await requireUser();
  const { mailbox: requested } = await searchParams;

  let folders: MailFolder[] = [];
  let mailboxes: MailboxInfo[] = [];
  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
  let inboxPath = "INBOX";
  let signature = "";
  let active: string | undefined;
  let failed = false;

  try {
    mailboxes = await getMailboxes();
    if (mailboxes.length === 0) throw new Error("no mailbox");

    // Honour `?mailbox=` (the per-mailbox "Open inbox" link on the Business
    // Email page) but ONLY when the address is one this user actually owns —
    // `getMailboxes` is already scoped to their own subscriptions, so an address
    // that isn't in that list is silently ignored rather than passed through to
    // `resolveMailbox`. A bad or hostile value therefore lands on the default
    // mailbox instead of turning the whole page into an error state.
    const wanted = requested?.trim().toLowerCase();
    active = wanted && mailboxes.some((m) => m.address.toLowerCase() === wanted) ? wanted : undefined;

    folders = await listFolders(active);
    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
    list = await listMessages(inboxPath, 1, undefined, active);
    // Signature for the active mailbox (best effort — never fail the page on it).
    signature = await getMailboxSettings(active)
      .then((s) => s.signature)
      .catch(() => "");
  } catch {
    failed = true;
  }

  if (failed || folders.length === 0) {
    // WHY a diagnosis instead of one message: this page used to render a single
    // "No mailbox connected" for every cause, so "you have no email plan",
    // "your domain isn't verified yet", "your mailbox exists but we never
    // captured its password" and "the mail server is down" all read as the same
    // dead end. `mailAccessState` also runs Mailcow discovery, so a mailbox that
    // exists on the mail server without a local row is adopted BEFORE we tell
    // anyone they don't have one — the "it's not detecting the mailbox I already
    // have" report.
    const state = await mailAccessState(user.id).catch(
      () => ({ kind: "no-subscription" }) as MailAccessState,
    );
    return (
      <div className="mx-auto max-w-2xl pt-10">
        <MailUnavailable state={state} />
      </div>
    );
  }

  // The shared dashboard <main> wraps every route in `max-w-7xl px-4 py-8
  // sm:px-6`. Mail is a full-app surface, so we cancel that padding with
  // negative margins to let the client run full-height (no blank space below)
  // and edge-to-edge up to the layout's max width. Going wider than max-w-7xl
  // on very large monitors would require editing the shared layout, which this
  // route intentionally leaves untouched.
  return (
    <div className="h-full">
      <MailClient
        initialFolders={folders}
        initialMailboxes={mailboxes}
        initialList={list}
        initialFolderPath={inboxPath}
        initialSignature={signature}
        initialActiveAddress={active}
      />
    </div>
  );
}

/** One empty state per real cause, each with the action that actually fixes it. */
function MailUnavailable({ state }: { state: MailAccessState }) {
  const emailLink = (
    <Link href="/dashboard/email" className="btn-primary">
      Business Email
    </Link>
  );

  switch (state.kind) {
    case "no-subscription":
      return (
        <EmptyState
          title="No email plan yet"
          sub="Webmail needs a mailbox on one of your domains. Add business email to a domain and your inbox appears here."
          action={
            <Link href="/dashboard/email" className="btn-primary">
              Set up email
            </Link>
          }
        />
      );

    case "unverified-domain":
      return (
        <EmptyState
          title="Finish verifying your domain"
          sub={`${state.domains.join(", ")} still needs its DNS records published and verified. Mailboxes can't go live — and mail won't route — until that succeeds.`}
          action={emailLink}
        />
      );

    case "no-mailbox":
      return (
        <EmptyState
          title="No mailbox created yet"
          sub={`${state.domains.join(", ")} is verified and ready. Create your first mailbox (like you@${state.domains[0] ?? "yourdomain.com"}) to start using webmail.`}
          action={emailLink}
        />
      );

    case "no-password":
      return (
        <EmptyState
          title="Reset your mailbox password to continue"
          sub={`We can see ${state.address} on the mail server, but we don't hold a password for it — so we can't sign in to IMAP on your behalf. Reset the password on the Business Email page and webmail will open here.`}
          action={emailLink}
        />
      );

    case "server-unreachable":
      return (
        <EmptyState
          title="Couldn't reach your mailbox"
          sub={`${state.address} is set up, but the mail server didn't answer just now. This is usually temporary — reload in a moment. If it keeps happening, open a ticket and we'll look at the server.`}
          action={
            <Link href="/dashboard/support" className="btn-secondary">
              Contact support
            </Link>
          }
        />
      );

    default:
      return (
        <EmptyState
          title="No mailbox connected"
          sub="We couldn't reach a mailbox for your account."
          action={emailLink}
        />
      );
  }
}

