/* -------------------------------------------------------------------------- */
/* Live rule status (auto-reply + forwarding)                                  */
/* -------------------------------------------------------------------------- */

/**
 * Read back what the MAIL SERVER is actually running for this mailbox.
 *
 * WHY this exists: both of these sections used to carry a hardcoded amber
 * "…is rolling out — until then these settings are stored but not sent"
 * notice. Auto-reply and forwarding really were store-only then; they are real
 * sieve now, so that fixed sentence had become a lie in the other direction —
 * telling a customer their working out-of-office does nothing. Neither the old
 * notice nor a hardcoded "Active ✓" would be honest, because neither asked the
 * server. This does ask, and reports the answer.
 *
 * `bump` is incremented after every successful save so the band re-reads the
 * live script rather than assuming the save took effect.
 */
function useRuleStatus(mailboxAddress: string | undefined, bump: number) {
  const [status, setStatus] = useState<MailRuleStatus | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    getMailRuleStatus(mailboxAddress)
      .then((s) => alive && setStatus(s))
      .catch(
        () =>
          alive &&
          // A thrown action (network/auth) must not render as "not active" —
          // that would be the same unverified claim in miniature.
          setStatus({
            supported: false,
            autoReplyLive: false,
            forwardingLive: false,
            error: "Couldn't reach the mail server to check this rule.",
          }),
      )
      .finally(() => alive && setLoading(false));
    return () => {
      alive = false;
    };
  }, [mailboxAddress, bump]);

  return { status, loading };
}

/**
 * State of one rule on the mail server, compared against what is saved here.
 *
 * The disagreement case (`savedOn && !live`) is the one worth surfacing loudly:
 * it is the only signal a customer gets that the push to the mail server did not
 * take, and it is the exact failure the old "Saved." toast used to hide.
 */
function RuleStatusNote({
  status,
  loading,
  live,
  savedOn,
  runningText,
}: {
  status: MailRuleStatus | null;
  loading: boolean;
  live: boolean;
  savedOn: boolean;
  runningText: string;
}) {
  const base = "rounded-xl border px-4 py-3 text-xs";
  if (loading || !status) {
    return (
      <div className={`${base} border-white/[0.08] bg-white/[0.03] text-slate-400`}>
        Checking what the mail server is running…
      </div>
    );
  }

  if (!status.supported) {
    return (
      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
        This rule is <span className="font-medium">not being applied on the mail server</span>.{" "}
        {status.error ?? "Mail rules are unavailable for this mailbox right now."}
      </div>
    );
  }

  if (live && savedOn) {
    return (
      <div className={`${base} border-emerald-400/25 bg-emerald-400/[0.07] text-emerald-200/90`}>
        Active on the mail server. {runningText}
      </div>
    );
  }

  if (savedOn && !live) {
    return (
      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
        Saved here, but the mail server is <span className="font-medium">not running it</span>. Press
        Save changes again — if this keeps coming back, the rule is not active and support should look at
        it.
      </div>
    );
  }

  if (live && !savedOn) {
    return (
      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
        The mail server is still running a rule for this mailbox even though it is switched off here.
        Press Save changes to remove it.
      </div>
    );
  }

  return (
    <div className={`${base} border-white/[0.08] bg-white/[0.03] text-slate-400`}>
      Off — the mail server is not running this rule.
    </div>
  );
}

