/**
 * Badge for a mailbox's REAL status.
 *
 * Every row used to render a literal `<Badge tone="amber">Provisioning</Badge>`
 * while the column moved through ACTIVE / FAILED / SUSPENDED underneath. When
 * Mailcow was down at creation time `provisionMailboxOnMailcow` set FAILED and
 * `addMailbox` still returned ok, so the row read "Provisioning" forever and
 * mail to that address bounced with nothing on screen suggesting a problem.
 */
function statusBadge(status: string): { tone: "green" | "amber" | "red" | "slate"; label: string } {
  switch (status) {
    case "ACTIVE":
      return { tone: "green", label: "Active" };
    case "FAILED":
      return { tone: "red", label: "Setup failed" };
    case "SUSPENDED":
      return { tone: "slate", label: "Suspended" };
    case "PROVISIONING":
      return { tone: "amber", label: "Provisioning" };
    default:
      // Never invent a friendly label for a value we don't know — show it raw so
      // an unmapped state is visible rather than silently rendered as healthy.
      return { tone: "slate", label: status || "Unknown" };
  }
}

function MailboxItem({ mailbox }: { mailbox: MailboxRow }) {
  const [pending, start] = useTransition();
  const [pwPending, startPw] = useTransition();
  const [retryPending, startRetry] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [password, setPassword] = useState<string | null>(null);
  const [pwNote, setPwNote] = useState<string | null>(null);
  const [status, setStatus] = useState(mailbox.status);

  const badge = statusBadge(status);
  // Only a live mailbox can actually be signed in to. Offering "Open inbox" on a
  // FAILED row would send the customer to a webmail error page instead of
  // telling them the mailbox was never created on the mail server.
  const usable = status === "ACTIVE";
  const retryable = status === "FAILED" || status === "PROVISIONING";

  function retry() {
    setError(null);
    setPwNote(null);
    startRetry(async () => {
      const res = await retryMailboxProvision(mailbox.id);
      if (res?.error) {
        setError(res.error);
        setStatus("FAILED");
      } else if (res?.ok) {
        setStatus("ACTIVE");
        setPwNote("Mailbox created on the mail server. Use Show password to sign in.");
      }
    });
  }

