/* -------------------------------------------------------------------------- */
/* Deliverability self-check                                                   */
/* -------------------------------------------------------------------------- */

const CHECK_TONE: Record<CheckStatus, "green" | "amber" | "red" | "slate"> = {
  pass: "green",
  warn: "amber",
  fail: "red",
  unknown: "slate",
};

const CHECK_LABEL: Record<CheckStatus, string> = {
  pass: "Pass",
  warn: "Warning",
  fail: "Fail",
  unknown: "Unknown",
};

/**
 * Per-domain SPF / DKIM / DMARC / MX self-check.
 *
 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
 * platform owner hit exactly this and had to diagnose it with an external
 * third-party tool, so every customer in the same position had no route at all.
 *
 * Two things this panel must never do, because both would make it the codebase's
 * recurring defect in a new place — a surface reporting an outcome it never
 * verified, here telling someone their mail is fine while it goes to spam:
 *
 *   1. Report a status the server did not derive from DNS. Every badge below
 *      comes from `checkEmailDeliverability`, which reads the zone's own
 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
 *      real query — that produced one confidently wrong diagnosis already).
 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
 *      as a pass, and the nameservers actually queried are printed so the result
 *      is auditable rather than taken on trust.
 *
 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
 * and the customer has to be looking at it for the answer to be useful.
 */
function DeliverabilityPanel({
  subscriptionId,
  domainName,
}: {
  subscriptionId: string;
  domainName: string;
}) {
  const [report, setReport] = useState<DeliverabilityReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function run() {
    setError(null);
    start(async () => {
      const res = await checkEmailDeliverability(subscriptionId);
      if (res?.error) {
        setError(res.error);
        setReport(null);
      } else if (res?.report) {
        setReport(res.report);
      }
    });
  }

  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;

  return (
    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm font-semibold text-white">Deliverability check</span>
          {report &&
            (failing > 0 ? (
              <Badge tone="red">
                {failing} problem{failing === 1 ? "" : "s"}
              </Badge>
            ) : unknown > 0 ? (
              <Badge tone="slate">Incomplete</Badge>
            ) : warning > 0 ? (
              <Badge tone="amber">
                {warning} warning{warning === 1 ? "" : "s"}
              </Badge>
            ) : (
              <Badge tone="green">All checks pass</Badge>
            ))}
        </div>
        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
        </button>
      </div>

      <p className="mt-2 text-xs text-slate-400">
        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
        and DMARC. If your mail is landing in spam, a failing row here is usually why.
      </p>

      {error && (
        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}

      {report && (
        <div className="mt-3 space-y-2">
          {report.error && (
            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
              {report.error}
            </div>
          )}

          {report.checks.map((c) => (
            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
              <div className="flex flex-wrap items-center gap-2">
                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
                <span className="text-sm font-medium text-slate-200">{c.label}</span>
                <span className="text-[11px] text-slate-500">
                  {c.type} · <span className="font-mono">{c.host}</span>
                </span>
              </div>

              <div className="mt-2 grid gap-2 sm:grid-cols-2">
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.observed || "— nothing published —"}
                  </code>
                </div>
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.expected || "—"}
                  </code>
                </div>
              </div>

              <p
                className={`mt-2 text-xs ${
                  c.status === "fail"
                    ? "text-red-400"
                    : c.status === "warn"
                      ? "text-amber-400"
                      : c.status === "pass"
                        ? "text-emerald-300/80"
                        : "text-slate-400"
                }`}
              >
                {c.detail}
              </p>
            </div>
          ))}

          {/* Printing the nameservers is the point, not decoration: it is how the
              customer (or support) can tell this answer came from the zone's own
              authority and not from a stale recursive cache. */}
          <p className="text-[11px] text-slate-500">
            {report.nameservers.length > 0 ? (
              <>
                Read directly from this domain&apos;s nameservers (
                <span className="font-mono">{report.nameservers.join(", ")}</span>), so a record you
                just changed shows up straight away.
              </>
            ) : (
              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
            )}{" "}
            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
          </p>
        </div>
      )}
    </div>
  );
}

