/**
 * Re-attempt Mailcow provisioning for a mailbox stuck in PROVISIONING/FAILED.
 * Owner-only (the caller must own the mailbox via its subscription).
 */
export async function retryMailboxProvision(mailboxId: string): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
  if (mailbox.subscription.status === "CANCELLED") {
    return { error: "This subscription is cancelled." };
  }
  // SECURITY: this creates a real mailbox on the shared Mailcow keyed by ADDRESS,
  // exactly like `addMailbox` — so it needs `addMailbox`'s verification gate too.
  // It had no callers until the "Retry setup" button on the mailbox row was
  // added, which would otherwise have made it a second, ungated door to the
  // cross-tenant takeover closed on 2026-07-25: owning the subscription ROW is
  // not proof of owning the DOMAIN.
  if (mailbox.subscription.external && !mailbox.subscription.verified) {
    return {
      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
    };
  }
  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };

